    /// <summary>
    /// Finds a specific <c>METVendorChangeRequest</c> record with given parameters.
    /// </summary>
    /// <param name = "_itemId">Item number.</param>
    /// <param name = "_siteId">Site ID.</param>
    /// <param name = "_effectiveDate">Change request effective date.</param>
    /// <param name = "_forUpdate">Determines whether the record is selected for update.</param>
    /// <param name = "_concurrencyModel">Determines the concurreny model when selecting <c>METVendorChangeRequest</c> record.</param>
    /// <returns>The record that is searched for.</returns>
    static METVendorChangeRequest find(ItemId                   _itemId,
                                 InventSiteId                   _siteId,
                                 METChangeRequestEffectiveDate  _effectiveDate,
                                 boolean                        _forUpdate = false,
                                 ConcurrencyModel               _concurrencyModel = ConcurrencyModel::Auto)
    {
        METVendorChangeRequest  vendorChangeRequest;

        if (_itemId && _siteId && _effectiveDate)
        {
            if (_forUpdate)
            {
                vendorChangeRequest.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    vendorChangeRequest.concurrencyModel(_concurrencyModel);
                }
            }

            select firstonly vendorChangeRequest
                where vendorChangeRequest.ItemId == _itemId
                    && vendorChangeRequest.SiteId == _siteId
                    && vendorChangeRequest.ChangeRequestEffectiveDate == _effectiveDate;
        }

        return vendorChangeRequest;
    }

    /// <summary>
    /// Checks if a specific <c>METVendorChangeRequest</c> record exists.
    /// </summary>
    /// <param name = "_itemId">Item number.</param>
    /// <param name = "_siteId">Site ID.</param>
    /// <param name = "_effectiveDate">Change request effective date.</param>
    /// <returns>True if the record exists; otherwise, false</returns>
    static boolean exist(ItemId                        _itemId,
                         InventSiteId                   _siteId,
                         METChangeRequestEffectiveDate _effectiveDate)
    {
        if (!_itemId || !_siteId || !_effectiveDate)
        {
            return false;
        }

        return (select firstonly RecId from METVendorChangeRequest
                    where METVendorChangeRequest.ItemID == _itemId
                        && METVendorChangeRequest.SiteId == _siteId
                        && METVendorChangeRequest.ChangeRequestEffectiveDate == _effectiveDate).RecId != 0;
    }

    /// <summary>
    /// Validate before saving the record to database.
    /// </summary>
    /// <returns>Return false when validation failed, Otherwise true.</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (this.ChangeRequestEffectiveDate < DateTimeUtil::utcNow())
        {
            ret = checkFailed("@MET:ChangeReqDateValidation");
        }
    
        return ret;
    }
